import os, sys

root = r"C:\Users\Derek\Desktop\heretek-swarm"

# Find the actual source root
for candidate in [os.path.join(root, "src", "heretek_swarm"), os.path.join(root, "heretek_swarm")]:
    if os.path.isdir(candidate):
        print(f"Source root: {candidate}")
        # List actors directory tree
        actors_dir = os.path.join(candidate, "actors")
        if os.path.isdir(actors_dir):
            for dirpath, dirnames, filenames in os.walk(actors_dir):
                rel = os.path.relpath(dirpath, candidate)
                for f in sorted(f for f in filenames if f.endswith(".py")):
                    print(f"  {rel}/{f}")

        # List tests directory tree
        tests_dir = os.path.join(root, "tests")
        if os.path.isdir(tests_dir):
            print("\nTests:")
            for dirpath, dirnames, filenames in os.walk(tests_dir):
                rel = os.path.relpath(dirpath, root)
                for f in sorted(f for f in filenames if f.endswith(".py")):
                    print(f"  {rel}/{f}")
        break

